  padding: 0;
  position: absolute;
  right: var(--lcl-fluid-shell-padding);
  top: var(--lcl-fluid-shell-padding);
  width: var(--lcl-size-control-min-height);
  z-index: 20;
}

.app-settings-trigger:hover,
.app-settings-trigger:focus-visible {
  border-color: var(--lcl-color-accent);
